import pathlib,json,statistics,hashlib
P=pathlib.Path('/workspace/scratch/module-scope-walk');data=json.loads((P/'benchmark.json').read_text());rows=data['records'];assert len(rows)==8
for r in rows:assert r['exit']==0 and not r['censored'] and not r['remaining_owned_processes']
assert len({r['stdout_sha256'] for r in rows})==1
for i in range(4):
 assert [r['label'] for r in rows[i*2:i*2+2]]==([f'{i}-baseline',f'{i}-candidate'] if i%2==0 else [f'{i}-candidate',f'{i}-baseline'])
b=json.loads((P/'baseline-binary.json').read_text());c=json.loads((P/'candidate-binary.json').read_text());assert b['artifact']['profile']==c['artifact']['profile'];assert b['artifact']['features']==c['artifact']['features']
stats={}
for variant in ['baseline','candidate']:
 selected=[r for r in rows if r['label'].endswith(variant)];stats[variant]={k:{'values':[r[k] for r in selected],'median':statistics.median(r[k] for r in selected),'min':min(r[k] for r in selected),'max':max(r[k] for r in selected)} for k in ['elapsed_s','cpu_s','maxrss_kib']}
result={'identity':{'baseline_source':b['source'],'candidate_source':c['source'],'baseline_binary_sha256':b['sha256'],'candidate_binary_sha256':c['sha256'],'matched_profile':b['artifact']['profile'],'matched_features':b['artifact']['features'],'input_hashes':data['input_hashes'],'input_bytes':data['input_bytes'],'functions':data['functions']},'pairs':4,'completed_runs':8,'complete_public_json_byte_identical':True,'stdout_sha256':rows[0]['stdout_sha256'],'stats':stats,'median_wall_reduction_percent':100*(1-stats['candidate']['elapsed_s']['median']/stats['baseline']['elapsed_s']['median']),'paired_wall_reduction_percent':[100*(1-next(r['elapsed_s'] for r in rows if r['label']==f'{i}-candidate')/next(r['elapsed_s'] for r in rows if r['label']==f'{i}-baseline')) for i in range(4)],'limits':['Single synthetic finite workload, four balanced serial alternating pairs; no broad or hosted runtime inference.','Initially absent RIPR caches are matched; OS page cache and host load are uncontrolled.','Dev opt-level0/default features/Linux x86_64 only; no release-profile or other-platform timing.','Wall timing uses10ms wait polling; reported CPU/RSS are root wait4 observations, not whole-process-tree resource profiling.','The preflight6.035s observation is excluded from paired statistics.','Binary hashes are streamed outside timed intervals to avoid inherited parent peak-RSS contamination.','No observer/profiler is attached during these timed runs.']}
(P/'comparison.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
